if len(sys.argv)!=2 or sys.argv[1] not in ('baseline','expanded'): raise SystemExit(64)
selected = CASES[:12] if sys.argv[1]=='baseline' else CASES
failures=0
for identifier,_,amount,currency,memo,limit,kind,expected_amount,reason in selected:
    actual=decide(amount,currency,memo,limit)
    expected={'Approved':lambda:Approved(expected_amount),'NeedsReview':lambda:NeedsReview(expected_amount),'Invalid':lambda:Invalid(reason)}[kind]()
    passed=actual==expected
    failures+=not passed
    print('CASE\t'+identifier+'\t'+('PASS' if passed else 'FAIL'))
raise SystemExit(1 if failures else 0)
